from dataclasses import dataclass


@dataclass(frozen=True)
class Buffer:
    n: int  # a whole buffer of n elements


@dataclass(frozen=True)
class Shrink:
    parent: "View"  # shrink parent off shape=[k]
    off: int
    k: int


@dataclass(frozen=True)
class Elem:
    parent: "View"  # shrink parent off shape=[]
    off: int


View = Buffer | Shrink | Elem


def resolve(v: View) -> tuple[int, int]:
    """Return (start, length): where v starts inside its buffer, and how many elements it covers.
    Raise ValueError("out of bounds") if any step doesn't fit inside its parent."""
    match v:
        case Buffer(n):
            return (0, n)
        case Shrink(p, off, k):
            return (resolve(p)[0] + off, k)
        case Elem(p, off):
            return (resolve(p)[0] + off, 1)
